export const getExportSpaceStatementCsvUrl = (spaceId: string,
    params: ExportSpaceStatementCsvParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/manage/spaces/${spaceId}/statement.csv?${stringifiedParams}` : `/v1/manage/spaces/${spaceId}/statement.csv`
}

/**
 * RF-PAY-03. Período por `paid_at` em UTC, meio-aberto: `from` ≤ pago < `to` (ISO 8601 com fuso). `service`: `RENTAL` (reserva e partes da conta dividida), `RECURRING` (mensalidade do mensalista) ou `CLASS`; `method`: forma de pagamento; `channel`: `ON_SITE` (registrado no espaço) ou `ONLINE` (pago pelo app, RN-ONPAY-04). O pagamento online entra pelo valor líquido de estornos (decisão 93). Um registro por linha, em ordem cronológica, inclusive estornados (com `estornado_em_utc`); UTF-8 com BOM e vírgula como separador. Datas em dd/mm/aaaa (`mensalidade_mes` em mm/aaaa); as locais, no fuso do espaço. Colunas: id, pago_em_utc, pago_em_local, servico, tipo, forma, canal (`no_local` ou `online`), valor_centavos, pagador, quadra, reserva_inicio_local, mensalidade_mes, registrado_por, observacao, estornado_em_utc.
 * @summary Exportar o extrato do período em CSV
 */
export const exportSpaceStatementCsv = async (spaceId: string,
    params: ExportSpaceStatementCsvParams, options?: Parameters<typeof customFetch>[1]): Promise<string> => {

  return customFetch<string>(getExportSpaceStatementCsvUrl(spaceId,params),
  {
    ...options,
    method: 'GET'


  }
);}





